static nes_t n,plain,ref;static cart_t cart;static uint8_t romid[8];static unsigned failures,checks;static int paired_native;
static int same(nes_t*a,nes_t*b);
#define CHECK(v) do{checks++;if(!(v)){fprintf(stderr,"FAIL line%d: %s\n",__LINE__,#v);failures++;}}while(0)
static unsigned readn(nes_t *c,unsigned a){return bus_peek(c,a);}
static void observe(nes_t *c,void *p){party_exec(c,p);}
static int load(nes_t*c,const char*p){nes_init(c,cart.prg,cart.prg_size);size_t z=nes_state_size();void*b=malloc(z);FILE*f=fopen(p,"rb");if(!f)return 0;size_t got=fread(b,1,z,f);fclose(f);int ok=nes_state_load(c,b,got,romid);free(b);return ok;}
static void known_history(party_state_t*p,unsigned first,unsigned second){party_history_t h={0};h.version=PARTY_HISTORY_VERSION;h.valid=1;h.initial_roster[0]=3;h.initial_roster[1]=first;h.initial_roster[2]=second;h.activated_mask=(1u<<2)|(1u<<(first-1))|(1u<<(second-1));h.starter_issued_mask=h.activated_mask;uint8_t encoded[PARTY_HISTORY_BYTES];CHECK(party_history_encode(&h,encoded));CHECK(party_restore_history(p,encoded,sizeof encoded));}
static void native_step(unsigned pad){nes_set_pad(&n,0,pad);nes_run_frame(&n);if(paired_native){nes_set_pad(&plain,0,pad);nes_run_frame(&plain);CHECK(same(&n,&plain));}}
static void native_wait(unsigned frames){while(frames--)native_step(0);}
static int native_seek(int x,int y){for(unsigned i=0;i<500;i++){int dx=x-(int)readn(&n,0x7116),dy=y-(int)readn(&n,0x7118);if(abs(dx)<=2&&abs(dy)<=2){native_step(0);return 1;}unsigned pad=0;if(dx>2)pad|=PAD_RIGHT;if(dx< -2)pad|=PAD_LEFT;if(dy>2)pad|=PAD_DOWN;if(dy< -2)pad|=PAD_UP;if(abs(dx)<12&&abs(dy)<12&&(i&1))pad=0;native_step(pad);}return 0;}
static int native_verb(unsigned id){for(unsigned i=0;i<20;i++)if(readn(&n,0x6ace + i)==id){int x=(readn(&n,0x6a96 + i)+readn(&n,0x6ab2 + i))*4+8,y=(readn(&n,0x6a5e + i)+readn(&n,0x6a7a + i))*4+2;if(!native_seek(x,y))return 0;native_wait(2);for(unsigned j=0;j<4;j++)native_step(PAD_A);native_wait(24);return 1;}return 0;}
static unsigned records(unsigned id){unsigned c=0;for(unsigned i=1;i<60;i++)c+=readn(&n,0x6260 + i)==id;return c;}
static unsigned record(nes_t*c,unsigned id){for(unsigned i=1;i<60;i++)if(readn(c,0x6260 + i)==id)return i;return 0;}
static int same(nes_t*a,nes_t*b){size_t z=nes_state_size();void*x=malloc(z),*y=malloc(z);nes_state_save(a,x,romid);nes_state_save(b,y,romid);int equal=!memcmp(x,y,z);free(x);free(y);return equal;}
int main(int argc,char**argv){if(argc<4)return 2;char e[512];if(!cart_load(&cart,argv[1],false,e,sizeof e)){fprintf(stderr,"%s\n",e);return 2;}for(unsigned i=0;i<8;i++){unsigned v;sscanf(cart.prg_sha256+2*i,"%2x",&v);romid[i]=v;}CHECK(load(&n,argv[2]));CHECK(load(&plain,argv[2]));CHECK(load(&ref,argv[3]));party_state_t p;party_init(&p);party_update(&p,false,true,true);n.exec_hook=observe;n.exec_hook_ud=&p;for(unsigned i=0;i<90;i++){nes_set_pad(&n,0,i<15?PAD_RIGHT:0);nes_set_pad(&plain,0,i<15?PAD_RIGHT:0);nes_run_frame(&n);nes_run_frame(&plain);CHECK(same(&n,&plain));}printf("Original actual native snapshots:90\n");party_destroy(&p);CHECK(load(&n,argv[2]));CHECK(load(&plain,argv[2]));party_init(&p);party_update(&p,true,false,true);n.exec_hook=observe;n.exec_hook_ud=&p;paired_native=1;native_wait(90);paired_native=0;printf("Enhanced optionOFF native snapshots:90\n");party_destroy(&p);CHECK(load(&n,argv[2]));party_init(&p);party_update(&p,true,true,true);CHECK(party_check(&n,&p,6,2)==PARTY_HISTORY_UNKNOWN);known_history(&p,1,6);CHECK(party_check(&n,&p,3,2)!=PARTY_OK);CHECK(party_check(&n,&p,6,1)!=PARTY_OK);n.exec_hook=observe;n.exec_hook_ud=&p;
for(unsigned cycle=0;cycle<3;cycle++){unsigned outgoing=cycle==1?2:6,incoming=cycle==1?6:2;party_result_t request=party_request(&n,&p,outgoing,incoming);printf("request cycle%u: %s\n",cycle,party_result_name(request));CHECK(request==PARTY_OK);for(unsigned f=0;f<180&&(p.pending||p.executing);f++){nes_set_pad(&n,0,0);nes_run_frame(&n);}printf("result cycle%u: %s\n",cycle,party_result_name(p.result));CHECK(!p.pending&&!p.executing);CHECK(p.result==PARTY_OK);CHECK(readn(&n,0x6100)==3);CHECK(readn(&n,0x6131)==incoming);CHECK(readn(&n,0x6b5d + incoming)==44);CHECK(readn(&n,0x6b5d + outgoing)==0);CHECK(readn(&n,0x6b43 + incoming)==incoming);CHECK(records(47)==1&&records(50)==1);CHECK((readn(&n,0x660a + 47)&15)==2);CHECK((readn(&n,0x660a + 50)&15)==6);for(unsigned f=0;f<30;f++)nes_run_frame(&n);}
CHECK(readn(&n,0x660a + 47)==readn(&ref,0x660a + 47));unsigned live=record(&n,47),original=record(&ref,47);CHECK(live&&original);unsigned tables[]={0x629c,0x62d8,0x6a22};for(unsigned i=0;i<3;i++)CHECK(readn(&n,tables[i]+live)==readn(&ref,tables[i]+original));CHECK(native_verb(7));CHECK(native_verb(22));native_wait(60);CHECK(readn(&n,0x6100)==2);CHECK(readn(&n,0x63c6)==44);CHECK(readn(&n,0x611a)==13);CHECK((readn(&n,0x660a + 47)&15)==2);printf("native NewKid chooses replacementRazor, camera44/nativeWalk13\n");uint8_t bytes[PARTY_HISTORY_BYTES];CHECK(party_history_encode(&p.history,bytes));party_history_t decoded;CHECK(party_history_decode(&decoded,bytes,sizeof bytes));CHECK(!memcmp(&decoded,&p.history,sizeof decoded));party_destroy(&p);
CHECK(load(&n,argv[2]));party_init(&p);known_history(&p,1,6);party_update(&p,true,true,true);for(unsigned i=1;i<60;i++)n.prgram[0x6260+i-0x6000]=1;CHECK(readn(&n,0x6260)==0);CHECK(party_check(&n,&p,6,2)==PARTY_STARTER_UNSAFE);party_destroy(&p);CHECK(load(&n,argv[2]));party_init(&p);known_history(&p,1,6);party_update(&p,true,true,true);n.prgram[0x612f-0x6000]=1;n.prgram[0x6130-0x6000]=3;CHECK(party_check(&n,&p,6,2)==PARTY_BAD_ROSTER);party_destroy(&p);printf("controlled fullinventory and malformedDave roster guards\n");
CHECK(load(&n,argv[2]));party_init(&p);known_history(&p,1,6);party_update(&p,true,true,true);n.exec_hook=observe;n.exec_hook_ud=&p;party_history_t before_history=p.history;CHECK(party_request(&n,&p,6,2)==PARTY_OK);for(unsigned f=0;f<180&&!p.executing&&p.pending;f++)native_step(0);CHECK(p.executing&&p.rollback);if(p.rollback){memcpy(&plain,p.rollback,sizeof plain);party_cancel(&n,&p);CHECK(same(&n,&plain));CHECK(!p.pending&&!p.executing);CHECK(!memcmp(&p.history,&before_history,sizeof before_history));printf("cancel restores actual pretransaction native snapshot/history\n");}party_destroy(&p);
for(int i=4;i<argc;i++){CHECK(load(&n,argv[i]));party_init(&p);known_history(&p,2,1);party_update(&p,true,true,true);party_result_t denied=party_check(&n,&p,2,6);printf("natural unsafe fixture: %s\n",party_result_name(denied));CHECK(denied!=PARTY_OK);party_destroy(&p);}printf("party native checks%u failures%u\n",checks,failures);cart_free(&cart);return failures?1:0;}
